```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.5)/1e6,3) med_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY ALL", "claim": "361 of 364 search-side calls to rate.Rate/GetRates return Error with median about 0.013 ms, i.e. fail before any connection."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.5)/1e6,3) med_ms FROM abnormal_traces WHERE service_name='rate' AND span_name='rate.Rate/GetRates' GROUP BY ALL", "claim": "Rate served only one GetRates span in the abnormal window versus about 1065 in normal, so requests from search never arrived."},
        {"kind": "metric", "sql": "SELECT service_name, attr_k8s_pod_name pod, metric, cast(floor((epoch(time) - (SELECT min(epoch(time)) FROM abnormal_metrics_sum))/60) as int) min_bin, count(*) n, min(value) vmin, max(value) vmax FROM abnormal_metrics_sum WHERE service_name='rate' AND metric='k8s.pod.uptime' GROUP BY ALL ORDER BY min_bin", "claim": "Rate pod uptime rises continuously across the abnormal window with no reset, so rate never restarted or became unavailable."}
      ]
    }
  ],
  "propagation": [
    {"from": "search", "to": "frontend", "evidence": [
      {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.5)/1e6,3) med_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='search.Search/Nearby') OR (service_name='frontend' AND span_name='HTTP /hotels') GROUP BY ALL", "claim": "All 301 frontend HTTP /hotels requests in the abnormal window return Error, matching search.Search/Nearby failures."}
    ]}
  ]
}
